import os,re,sys
base=sys.argv[1]; os.chdir(base)
exclude_scratch = True
def strip(txt):
    # remove nested block comments
    out=[];i=0;d=0
    while i<len(txt):
        if txt.startswith('/-',i): d+=1;i+=2;continue
        if txt.startswith('-/',i) and d>0: d-=1;i+=2;continue
        if d==0:
            if txt.startswith('--',i):
                j=txt.find('\n',i); i=len(txt) if j<0 else j; continue
            out.append(txt[i])
        i+=1
    return ''.join(out)
tot=0; files={}
